import { type ClassValue, clsx } from "clsx";
import { twMerge } from "tailwind-merge";

export function cn(...inputs: ClassValue[]) {
  return twMerge(clsx(inputs));
}

import type * as React from "react";

/**
 * The Sistine material system — the single source of the material → markup mapping.
 *
 * FIVE materials (glass, frosted, crystal, chakra, opaque), each a `[data-material]` token set in
 * app/theme/materials.css, composed with orthogonal AXES (border + its colour, veil, size, gradient, glow, sheen)
 * over the one structural `glass` utility. Components call `glassMaterial()` instead of hardcoding
 * recipe class strings (check-theme bans the legacy `glass-bg`/`glass-surface`/… classes).
 *
 * Semantics:
 * - `material` UNDEFINED = adaptive: no attribute is rendered; the surface follows the page's
 *   [data-glass] style (the default everywhere).
 * - An explicit material PINS the element under any page style, and — because the token set is
 *   inherited custom properties — also acts as a scoped default for adaptive glass descendants
 *   (a dialog set to frosted re-skins the controls inside it; pin a child back with its own material).
 * - `"none"` = not a glass surface: the helper returns nothing and the component supplies its plain
 *   (shadcn) classes.
 */
export type Material = "glass" | "frosted" | "crystal" | "chakra" | "opaque" | "none";

export interface MaterialProps {
  /** undefined = adaptive (follows the page style); "none" = the component's plain fallback. */
  material?: Material;
  /** Material border. Three weights: `true`/"hairline" = the material's edge (1px; 0.5px under
   *  frosted), "rim" = 2px, "frame" = 4px. */
  border?: boolean | "hairline" | "rim" | "frame";
  /** The border's COLOUR. "glass" (the default) = the material's own edge, a near-white rim at the
   *  material's alpha, which reads as glass but disappears on light themes at any weight. "ink" = the
   *  page's text colour (--foreground, at --glass-border-ink-a), a visible line wherever text is legible.
   *  Pairs with `border`; under the opaque page style it also colours the uniform panel edge. */
  borderColor?: "glass" | "ink";
  /** Element-composed legibility floor for read-through overlays (menus, tooltips, toasts). */
  veil?: boolean;
  /** Blur/elevation tier — INTERNAL: set by a component's ROLE (glass-sm/-lg), not a public prop
   *  ("size" universally means a component's dimensions; the material tier must never shadow that). */
  size?: "sm" | "lg" | "xl";
  /** Readability blur FLOOR (>= --glass-diffuse, default 12px) for text-dense translucent surfaces;
   *  inert under opaque. "stained" = the dyed mode: same floor, plus true stained-glass optics — the
   *  backdrop renders as TONAL SHADES of the theme hue (grayscale luminance collapse — the tint supplies the color). */
  diffuse?: boolean | "stained";
  /** Brand-gradient accent layered over the material. */
  gradient?: boolean;
  /** Resting glow, or the intensified "lg" halo. */
  glow?: boolean | "lg";
  /** Opt-in hover shimmer (pseudo-element based — avoid on sticky/fixed surfaces). */
  sheen?: boolean;
}

/** The PUBLIC per-instance axis props a component spreads onto its type. Excludes `size` (the material
 *  blur tier is a role-internal detail — a component's own `size` prop owns that name). */
export type MaterialAxisProps = Omit<MaterialProps, "size">;

/** The `rest` side of splitAxisProps. Distributes over union props (DayPicker's mode union, Radix
 *  ToggleGroup's single/multiple) so a discriminated union survives the split instead of collapsing
 *  under a bare Omit. */
export type SplitAxisRest<P> = P extends unknown ? Omit<P, keyof MaterialAxisProps> : never;

/** Split the material axis props off a component's props in ONE place — components never enumerate
 *  axis keys, so a NEW axis is zero-touch: extend MaterialProps + this destructure, done. `size` is
 *  role-internal (not in MaterialAxisProps) and stays in `rest` for the component's own cva. */
export function splitAxisProps<P extends MaterialAxisProps>(
  props: P,
): [
  MaterialAxisProps,
  SplitAxisRest<P>,
] {
  const { material, border, borderColor, veil, diffuse, gradient, glow, sheen, ...rest } = props;
  return [
    {
      material,
      border,
      borderColor,
      veil,
      diffuse,
      gradient,
      glow,
      sheen,
    },
    /* The conditional (distributive) rest type can't be proven for an unresolved P — safe by
     * construction: rest is exactly P minus the axis keys. */
    rest as SplitAxisRest<P>,
  ];
}

export interface MaterialAttrs {
  /** Spread-ready: undefined for adaptive and "none". */
  "data-material"?: Exclude<Material, "none">;
  /** "" when material === "none" (caller supplies its plain classes). */
  className: string;
}

export function glassMaterial(props: MaterialProps = {}): MaterialAttrs {
  const { material, border, borderColor, veil, size, diffuse, gradient, glow, sheen } = props;
  if (material === "none") {
    return {
      className: "",
    };
  }
  return {
    "data-material": material,
    className: [
      "glass",
      border && "glass-border",
      border === "rim" && "glass-border-rim",
      border === "frame" && "glass-border-frame",
      borderColor === "ink" && "glass-border-ink",
      veil && "glass-veil",
      size === "sm" && "glass-sm",
      size === "lg" && "glass-lg",
      size === "xl" && "glass-xl",
      diffuse && "glass-diffuse",
      diffuse === "stained" && "glass-stained",
      gradient && "glass-gradient",
      glow === "lg" ? "glass-glow-lg" : glow ? "glass-glow" : false,
      sheen && "glass-sheen",
    ]
      .filter(Boolean)
      .join(" "),
  };
}

/**
 * The component-facing resolver: merge a component's ROLE (its default axes for a given semantic
 * variant) with explicit per-instance material/axis props, and return the surface markup — or null
 * when the element is NOT a glass surface (role === null, or material === "none").
 *
 * Explicit props override the role per-axis; unspecified axes fall back to the role.
 */
export function materialSurface(role: MaterialProps | null, props: MaterialProps): MaterialAttrs | null {
  if (props.material === "none" || role === null) {
    return null;
  }
  return glassMaterial({
    material: props.material,
    border: props.border ?? role.border,
    borderColor: props.borderColor ?? role.borderColor,
    veil: props.veil ?? role.veil,
    size: props.size ?? role.size,
    diffuse: props.diffuse ?? role.diffuse,
    gradient: props.gradient ?? role.gradient,
    glow: props.glow ?? role.glow,
    sheen: props.sheen ?? role.sheen,
  });
}

/**
 * Typed per-element knobs → CSS custom properties ONLY (the cascade-native successor to the old
 * `glass={{…}}` inline-style prop). Everything routes through the token system, so nothing here can
 * fight a material, a page style, or the theme.
 *
 * The tint* keys recolor engine-composed tokens, which re-resolve at grouped declarations — pair
 * them with a `data-glass-tint` attribute on the same element so the engine re-composes there.
 */
export interface GlassVars {
  /** → --glass-tint-h (surface hue) */
  tintH?: number;
  /** → --glass-tint-c (surface chroma — the colorfulness master) */
  tintC?: number;
  /** → --glass-tint-a (tint film alpha) */
  tintA?: number;
  /** → --glass-opacity (0..1 solidify dial; element-composed in `glass`) */
  opacity?: number;
  /** → --srf-blur (number → px; glass material only) */
  blur?: number | string;
  /** → --glass-solid-a (veil floor alpha; element-composed in `glass-veil`) */
  solidA?: number;
}

export function glassVars(v: GlassVars = {}): React.CSSProperties {
  const s: Record<string, string> = {};
  if (v.tintH !== undefined) {
    s["--glass-tint-h"] = String(v.tintH);
  }
  if (v.tintC !== undefined) {
    s["--glass-tint-c"] = String(v.tintC);
  }
  if (v.tintA !== undefined) {
    s["--glass-tint-a"] = String(v.tintA);
  }
  if (v.opacity !== undefined) {
    s["--glass-opacity"] = String(v.opacity);
  }
  if (v.blur !== undefined) {
    s["--srf-blur"] = typeof v.blur === "number" ? `${v.blur}px` : v.blur;
  }
  if (v.solidA !== undefined) {
    s["--glass-solid-a"] = String(v.solidA);
  }
  return s as React.CSSProperties;
}

import { cva } from "class-variance-authority";

/**
 * Shared hover effect variants for all Sistine components
 *
 * Effects:
 * - none: No hover effect
 * - glow: Themed glow shadow (--glass-glow, follows the tint hue) that intensifies on hover
 * - shimmer: Moving shimmer effect across the component
 * - ripple: Ripple effect that scales outward on hover
 * - lift: Subtle lift effect with shadow increase
 * - scale: Scale up slightly on hover
 */
export const hoverEffects = cva("transition duration-300", {
  variants: {
    hover: {
      none: "",
      glow: "glass-glow hover:glass-glow-lg",
      shimmer:
        "relative overflow-hidden before:absolute before:inset-0 before:-translate-x-full before:bg-gradient-to-r before:from-transparent before:via-white/20 before:to-transparent hover:before:translate-x-full before:transition-transform before:duration-1000",
      ripple:
        "relative overflow-hidden after:absolute after:inset-0 after:scale-0 after:rounded-full after:bg-white/30 after:transition-transform after:duration-500 hover:after:scale-150",
      lift: "hover:-translate-y-1 hover:shadow-lg",
      scale: "hover:scale-105",
    },
  },
  defaultVariants: {
    hover: "none",
  },
});

export type HoverEffect = "none" | "glow" | "shimmer" | "ripple" | "lift" | "scale";

"use client";

import * as React from "react";

/**
 * Keeps text crisp on Radix popper surfaces (dropdown-menu, popover, tooltip, select, hover-card,
 * context-menu).
 *
 * THE DEFECT: on a high-density display the text in a popper rendered visibly soft. Radix positions the
 * surface with an inline `transform: translate(x, y)` on a wrapper element, written from Floating UI's
 * `floatingStyles`, and at a device pixel ratio of 1.5 or more Floating UI adds `will-change: transform`
 * to the same style (`@floating-ui/react-dom`, `floatingStyles`). `will-change` promotes the wrapper to
 * its own compositing layer, and WebKit drops subpixel (LCD) antialiasing for text on a composited layer;
 * sistine's popper content is glass, so a blurred backdrop sits right behind that text. Resetting
 * `will-change` to `auto` is the fix. The cost is a repaint on reposition instead of a layer move, for a
 * surface that is open for seconds.
 *
 * The ROUNDING below predates that diagnosis. Its premise was that unrounded offsets put glyphs off the
 * pixel grid, but Floating UI already rounds x/y to the device pixel grid (`roundByDPR`) before writing
 * them. It is kept for browser zoom, where the device grid and the CSS-pixel grid diverge, which has not
 * been verified either way; it is cheap and harmless, and removing it is a separate decision.
 *
 * Radix rewrites the style on scroll, resize and collision flips, so a MutationObserver re-applies both
 * after each write. The observer is re-entrant (our own write retriggers it), so each write is skipped
 * when the value is already what we want, which terminates the loop on the second pass at the latest.
 */
/**
 * The whole snap, as a pure string transform: given the wrapper's SPECIFIED inline `transform`, return
 * what it should be rewritten to, or `null` to leave it alone.
 *
 * Returning null is load-bearing in two cases and both are re-entrancy guards, since our own write
 * retriggers the MutationObserver that called us:
 *   - the value is already integral, so there is nothing to do and the loop terminates on pass one;
 *   - the value isn't a translate we recognise (Radix hasn't positioned yet), so we must not invent one.
 *
 * Split out of the hook so it can be checked without a DOM — see tests/snap-popper.test.tsx.
 */
export function snapTransform(specified: string): string | null {
  const parts = /^translate(?:3d)?\(\s*(-?[\d.]+)px\s*,\s*(-?[\d.]+)px/.exec(specified);
  if (!parts) return null;
  const next = `translate(${Math.round(Number(parts[1]))}px, ${Math.round(Number(parts[2]))}px)`;
  return specified === next ? null : next;
}

export function useSnappedPopper<T extends HTMLElement>(): React.RefCallback<T> {
  const cleanupRef = React.useRef<(() => void) | null>(null);

  return React.useCallback((node: T | null) => {
    cleanupRef.current?.();
    cleanupRef.current = null;
    if (!node) return;

    const wrapper = node.closest<HTMLElement>("[data-radix-popper-content-wrapper]");
    if (!wrapper) return; // not popper-positioned (e.g. an inline/anchored render) — nothing to snap

    const snap = () => {
      // Read and write the SPECIFIED value, never the computed one. Under browser `zoom` the computed
      // transform is in a scaled space, so rounding it and writing the result back as authored px
      // never converges — snapTransform's equality guard would never hold and the observer would
      // re-enter forever.
      const next = snapTransform(wrapper.style.transform);
      if (next !== null) wrapper.style.transform = next;
      // Floating UI's will-change (DPR >= 1.5) is what costs the text its antialiasing. Only written when
      // something else is set, so the pass our own write triggers sees `auto` and stops.
      const willChange = wrapper.style.willChange;
      if (willChange !== "" && willChange !== "auto") wrapper.style.willChange = "auto";
    };

    snap();
    const observer = new MutationObserver(snap);
    observer.observe(wrapper, {
      attributes: true,
      attributeFilter: [
        "style",
      ],
    });
    cleanupRef.current = () => observer.disconnect();
  }, []);
}

/**
 * Merge the forwarded ref with the snapping ref, MEMOIZED — use this, not `composeRefs`, in JSX.
 *
 * A ref callback written inline gets a fresh identity on every render, and React responds by detaching
 * the old one (calling it with `null`) and attaching the new one. For a plain ref that is merely
 * wasteful; here the detach runs `useSnappedPopper`'s cleanup, so the MutationObserver watching the
 * popper wrapper is torn down and rebuilt on every single render of the surface.
 *
 * Same shape as Radix's own `useComposedRefs` — `useCallback` over the composed callback, with the
 * refs themselves as the dependency array, so the identity holds as long as the individual refs do.
 * Kept local rather than importing @radix-ui/react-compose-refs: these components ship through the
 * registry, and a direct dependency would have to be declared on all six of them.
 */
export function useComposedRefs<T>(...refs: (React.Ref<T> | undefined)[]): React.RefCallback<T> {
  /* The spread refs ARE the dependency list — the identity holds while each individual ref does. */
  return React.useCallback(composeRefs(...refs), refs);
}

/** Merge the forwarded ref with the snapping ref — both need the same node. Prefer the memoized
 *  {@link useComposedRefs} anywhere the result is handed to JSX. */
export function composeRefs<T>(...refs: (React.Ref<T> | undefined)[]): React.RefCallback<T> {
  return (node: T | null) => {
    for (const ref of refs) {
      if (typeof ref === "function") ref(node);
      else if (ref) (ref as React.MutableRefObject<T | null>).current = node;
    }
  };
}

"use client";

import { CaretRightIcon, CheckIcon, CircleIcon } from "@phosphor-icons/react";
import { Menubar as MenubarPrimitive } from "radix-ui";
import type * as React from "react";

import { type MaterialAxisProps, materialSurface, splitAxisProps } from "@/lib/material";
import { useComposedRefs, useSnappedPopper } from "@/lib/snap-popper";
import { cn } from "@/lib/utils";

/**
 * A desktop-style menu bar (File, Edit, View…) on Radix Menubar: keyboard roving between menus, typeahead,
 * sub menus. The bar is bordered glass; its menus are bordered, veiled glass like DropdownMenu's, and like
 * those they render in a portal, sub menus included (a glass menu's backdrop-filter makes it the
 * containing block of a fixed-position child, so an unportaled sub menu is clipped by its parent).
 *
 * `menu-bar` is the older Sistine component of a similar name: a row of buttons, not a menu system.
 */

/* Role: the bar is bordered adaptive glass; its menus are bordered + veiled (read-through overlays). */
const BAR_ROLE = {
  border: true,
};
const MENU_ROLE = {
  border: true,
  veil: true,
};

const MENU_SURFACE =
  "z-50 overflow-hidden rounded-xl p-1 text-foreground shadow-lg data-[state=open]:animate-in data-[state=closed]:animate-out data-[state=closed]:fade-out-0 data-[state=open]:fade-in-0 data-[state=closed]:zoom-out-95 data-[state=open]:zoom-in-95 data-[side=bottom]:slide-in-from-top-2 data-[side=left]:slide-in-from-right-2 data-[side=right]:slide-in-from-left-2 data-[side=top]:slide-in-from-bottom-2";
const PLAIN_MENU = "bg-popover text-popover-foreground border";

function Menubar({
  className,
  variant = "glass",
  ...props
}: React.ComponentProps<typeof MenubarPrimitive.Root> &
  MaterialAxisProps & {
    variant?: "default" | "glass";
  }) {
  const [axes, rest] = splitAxisProps(props);
  const m = materialSurface(variant === "default" ? null : BAR_ROLE, axes);

  return (
    <MenubarPrimitive.Root
      data-slot="menubar"
      data-material={m?.["data-material"]}
      className={cn(
        m?.className,
        "flex h-9 items-center gap-1 rounded-xl p-1 text-foreground",
        variant === "default" && "border bg-background",
        className,
      )}
      {...rest}
    />
  );
}

function MenubarMenu({ ...props }: React.ComponentProps<typeof MenubarPrimitive.Menu>) {
  return <MenubarPrimitive.Menu data-slot="menubar-menu" {...props} />;
}

function MenubarGroup({ ...props }: React.ComponentProps<typeof MenubarPrimitive.Group>) {
  return <MenubarPrimitive.Group data-slot="menubar-group" {...props} />;
}

function MenubarPortal({ ...props }: React.ComponentProps<typeof MenubarPrimitive.Portal>) {
  return <MenubarPrimitive.Portal data-slot="menubar-portal" {...props} />;
}

function MenubarRadioGroup({ ...props }: React.ComponentProps<typeof MenubarPrimitive.RadioGroup>) {
  return <MenubarPrimitive.RadioGroup data-slot="menubar-radio-group" {...props} />;
}

function MenubarTrigger({ className, ...props }: React.ComponentProps<typeof MenubarPrimitive.Trigger>) {
  return (
    <MenubarPrimitive.Trigger
      data-slot="menubar-trigger"
      className={cn(
        "flex cursor-default items-center rounded-md px-2 py-1 text-sm font-medium outline-none select-none hover:bg-accent focus:bg-accent focus:text-accent-foreground data-[state=open]:bg-accent data-[state=open]:text-accent-foreground",
        className,
      )}
      {...props}
    />
  );
}

function MenubarContent({
  className,
  align = "start",
  alignOffset = -4,
  sideOffset = 8,
  variant = "glass",
  ref,
  ...props
}: React.ComponentProps<typeof MenubarPrimitive.Content> &
  MaterialAxisProps & {
    variant?: "default" | "glass";
  }) {
  const [axes, rest] = splitAxisProps(props);
  const snapRef = useSnappedPopper<HTMLDivElement>();
  const composedRef = useComposedRefs<HTMLDivElement>(ref, snapRef);
  const m = materialSurface(variant === "default" ? null : MENU_ROLE, axes);

  return (
    <MenubarPortal>
      <MenubarPrimitive.Content
        ref={composedRef}
        data-slot="menubar-content"
        data-material={m?.["data-material"]}
        align={align}
        alignOffset={alignOffset}
        sideOffset={sideOffset}
        className={cn(
          m?.className,
          "min-w-48 origin-(--radix-menubar-content-transform-origin)",
          MENU_SURFACE,
          variant === "default" && PLAIN_MENU,
          className,
        )}
        {...rest}
      />
    </MenubarPortal>
  );
}

function MenubarItem({
  className,
  inset,
  variant = "default",
  ...props
}: React.ComponentProps<typeof MenubarPrimitive.Item> & {
  inset?: boolean;
  variant?: "default" | "destructive";
}) {
  return (
    <MenubarPrimitive.Item
      data-slot="menubar-item"
      data-inset={inset}
      data-variant={variant}
      className={cn(
        "group/menubar-item relative flex cursor-default select-none items-center gap-2 rounded-sm px-2 py-1.5 text-sm outline-none transition-colors focus:bg-accent focus:text-accent-foreground data-[disabled]:pointer-events-none data-[disabled]:opacity-50 data-[inset]:pl-8 data-[variant=destructive]:text-destructive data-[variant=destructive]:focus:bg-destructive/10 data-[variant=destructive]:focus:text-destructive dark:data-[variant=destructive]:focus:bg-destructive/20 [&_svg]:pointer-events-none [&_svg]:shrink-0 [&_svg:not([class*='size-'])]:size-4 [&_svg:not([class*='text-'])]:text-muted-foreground data-[variant=destructive]:*:[svg]:text-destructive!",
        className,
      )}
      {...props}
    />
  );
}

function MenubarCheckboxItem({ className, children, checked, ...props }: React.ComponentProps<typeof MenubarPrimitive.CheckboxItem>) {
  return (
    <MenubarPrimitive.CheckboxItem
      data-slot="menubar-checkbox-item"
      className={cn(
        "relative flex cursor-default select-none items-center gap-2 rounded-sm py-1.5 pr-2 pl-8 text-sm outline-none transition-colors focus:bg-accent focus:text-accent-foreground data-[disabled]:pointer-events-none data-[disabled]:opacity-50 [&_svg]:pointer-events-none [&_svg]:shrink-0 [&_svg:not([class*='size-'])]:size-4",
        className,
      )}
      checked={checked}
      {...props}
    >
      <span className="pointer-events-none absolute left-2 flex size-3.5 items-center justify-center">
        <MenubarPrimitive.ItemIndicator>
          <CheckIcon className="size-4" />
        </MenubarPrimitive.ItemIndicator>
      </span>
      {children}
    </MenubarPrimitive.CheckboxItem>
  );
}

function MenubarRadioItem({ className, children, ...props }: React.ComponentProps<typeof MenubarPrimitive.RadioItem>) {
  return (
    <MenubarPrimitive.RadioItem
      data-slot="menubar-radio-item"
      className={cn(
        "relative flex cursor-default select-none items-center gap-2 rounded-sm py-1.5 pr-2 pl-8 text-sm outline-none transition-colors focus:bg-accent focus:text-accent-foreground data-[disabled]:pointer-events-none data-[disabled]:opacity-50 [&_svg]:pointer-events-none [&_svg]:shrink-0 [&_svg:not([class*='size-'])]:size-4",
        className,
      )}
      {...props}
    >
      <span className="pointer-events-none absolute left-2 flex size-3.5 items-center justify-center">
        <MenubarPrimitive.ItemIndicator>
          <CircleIcon weight="fill" className="size-2" />
        </MenubarPrimitive.ItemIndicator>
      </span>
      {children}
    </MenubarPrimitive.RadioItem>
  );
}

function MenubarLabel({
  className,
  inset,
  ...props
}: React.ComponentProps<typeof MenubarPrimitive.Label> & {
  inset?: boolean;
}) {
  return (
    <MenubarPrimitive.Label
      data-slot="menubar-label"
      data-inset={inset}
      className={cn("px-2 py-1.5 text-sm font-semibold data-[inset]:pl-8", className)}
      {...props}
    />
  );
}

function MenubarSeparator({ className, ...props }: React.ComponentProps<typeof MenubarPrimitive.Separator>) {
  return <MenubarPrimitive.Separator data-slot="menubar-separator" className={cn("-mx-1 my-1 h-px bg-muted", className)} {...props} />;
}

function MenubarShortcut({ className, ...props }: React.ComponentProps<"span">) {
  return (
    <span
      data-slot="menubar-shortcut"
      className={cn("ml-auto text-xs tracking-widest opacity-60 group-focus/menubar-item:text-accent-foreground", className)}
      {...props}
    />
  );
}

function MenubarSub({ ...props }: React.ComponentProps<typeof MenubarPrimitive.Sub>) {
  return <MenubarPrimitive.Sub data-slot="menubar-sub" {...props} />;
}

function MenubarSubTrigger({
  className,
  inset,
  children,
  ...props
}: React.ComponentProps<typeof MenubarPrimitive.SubTrigger> & {
  inset?: boolean;
}) {
  return (
    <MenubarPrimitive.SubTrigger
      data-slot="menubar-sub-trigger"
      data-inset={inset}
      className={cn(
        "flex cursor-default select-none items-center gap-2 rounded-sm px-2 py-1.5 text-sm outline-none focus:bg-accent focus:text-accent-foreground data-[inset]:pl-8 data-[state=open]:bg-accent data-[state=open]:text-accent-foreground [&_svg]:pointer-events-none [&_svg]:shrink-0 [&_svg:not([class*='size-'])]:size-4",
        className,
      )}
      {...props}
    >
      {children}
      <CaretRightIcon className="ml-auto size-4" />
    </MenubarPrimitive.SubTrigger>
  );
}

function MenubarSubContent({
  className,
  variant = "glass",
  ref,
  ...props
}: React.ComponentProps<typeof MenubarPrimitive.SubContent> &
  MaterialAxisProps & {
    variant?: "default" | "glass";
  }) {
  const [axes, rest] = splitAxisProps(props);
  const snapRef = useSnappedPopper<HTMLDivElement>();
  const composedRef = useComposedRefs<HTMLDivElement>(ref, snapRef);
  const m = materialSurface(variant === "default" ? null : MENU_ROLE, axes);

  return (
    <MenubarPortal>
      <MenubarPrimitive.SubContent
        ref={composedRef}
        data-slot="menubar-sub-content"
        data-material={m?.["data-material"]}
        className={cn(
          m?.className,
          "min-w-32 origin-(--radix-menubar-content-transform-origin)",
          MENU_SURFACE,
          variant === "default" && PLAIN_MENU,
          className,
        )}
        {...rest}
      />
    </MenubarPortal>
  );
}

